(function(){
  const seed={marketMakers:['Atlas','Vértice','Orion'],sites:['Casa que Pensa','Café de Origem','Escolha Pet'],nichos:['Casa inteligente','Cafés especiais','Cuidados para pets'],produtos:['Lâmpada Smart','Moedor Manual','Kit Passeio']};
  function boot(){const side=document.querySelector('.side'),main=document.querySelector('.main');if(!side||!main||main.querySelector('#cadastros'))return;const nav=document.createElement('button');nav.className='nav';nav.innerHTML='▣ <span>Cadastros</span>';const labels=[...side.querySelectorAll('.section-label')],anchor=labels.find(x=>x.textContent.trim().toLowerCase()==='administração')||null;side.insertBefore(nav,anchor);const view=document.createElement('section');view.className='view';view.id='cadastros';view.innerHTML='<section class="card"><div class="head"><div><h2>Cadastros operacionais</h2><span class="muted">Adicionar, editar e remover dados do Core</span></div><span class="pill">Manual/mock</span></div><div class="toolbar" id="crudTabs"><button class="btn primary" data-k="marketMakers">Market Makers</button><button class="btn" data-k="sites">Sites</button><button class="btn" data-k="nichos">Nichos</button><button class="btn" data-k="produtos">Produtos</button><button class="btn primary" id="crudAdd">+ Adicionar</button></div><div id="crudList"></div></section>';main.appendChild(view);let current='marketMakers',data=JSON.parse(localStorage.getItem('traficcagent-core-cadastros')||'null')||seed;const save=()=>localStorage.setItem('traficcagent-core-cadastros',JSON.stringify(data));const list=view.querySelector('#crudList');function paint(){list.innerHTML='<table><thead><tr><th>Nome</th><th>Ações</th></tr></thead><tbody>'+data[current].map((x,i)=>'<tr><td><b>'+escapeHTML(x)+'</b></td><td><button class="btn edit" data-i="'+i+'">Editar</button> <button class="btn remove" data-i="'+i+'">Remover</button></td></tr>').join('')+'</tbody></table>';view.querySelectorAll('[data-k]').forEach(b=>b.classList.toggle('primary',b.dataset.k===current))}view.querySelector('#crudTabs').onclick=e=>{const b=e.target.closest('[data-k]');if(b){current=b.dataset.k;paint()}const action=e.target.closest('.edit,.remove');if(action){const i=+action.dataset.i;if(action.classList.contains('edit')){const v=prompt('Alterar cadastro:',data[current][i]);if(v&&v.trim())data[current][i]=v.trim()}else if(confirm('Remover '+data[current][i]+'?'))data[current].splice(i,1);save();paint()}};view.querySelector('#crudAdd').onclick=()=>{const v=prompt('Novo '+current+':');if(v&&v.trim()){data[current].push(v.trim());save();paint()}};nav.onclick=()=>{document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));view.classList.add('active');document.querySelectorAll('.nav').forEach(x=>x.classList.remove('active'));nav.classList.add('active');document.querySelector('#title').textContent='Cadastros operacionais';document.querySelector('#subtitle').textContent='Market Makers, sites, nichos e produtos';};paint()}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else setTimeout(boot,40)})();
